const input = $input.first().json;
const produit = $('Get Produit A_Poster').first().json;

// Parser la reponse JSON de l'analyse
let analyse;
try {
  // Extraire le JSON de la reponse (peut etre dans message.content ou directement)
  const content = input.message?.content || (Array.isArray(input.content) ? input.content[0].text : input.content) || input.text || JSON.stringify(input);
  // Nettoyer le contenu (enlever les balises markdown si presentes)
  const cleanContent = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  analyse = JSON.parse(cleanContent);
} catch (e) {
  analyse = {
    type_produit: produit.categorie || 'produit',
    couleur_principale: 'inconnue',
    couleurs_secondaires: [],
    materiau: 'inconnu',
    caracteristiques: [],
    taille: 'standard',
    contexte_utilisation_suggere: 'bureau'
  };
}

return {
  json: {
    produit_id: produit.id,
    reference: produit.reference,
    nom_produit: produit.nom_produit,
    categorie: produit.categorie,
    url_image: produit.url_image,
    analyse: analyse
  }
};

